package ru.neverland.townymarket.personal;

import java.util.*;
import java.util.concurrent.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.command.CommandSender;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
import ru.neverland.core.*;
import ru.neverland.townymarket.MarketService;
import ru.neverland.townymarket.MarketData;
import static ru.neverland.townymarket.personal.LimitBook.*;

/** Separate, funded personal order book. Every non-idempotent external mutation has a prior durable pending receipt. */
public final class LimitService implements Listener {
    public record Offer(UUID token,UUID owner,Side side,String product,int quantity,long cents,long expires){}
    private final JavaPlugin plugin;private final LimitRepository repository;private final LimitBank bank;private final PlayerSaveEvidence inventoryEvidence;private final LimitAudit auditQueue;
    private Set<String> products=Set.of();private String configIssue="";private volatile boolean enabled;private boolean busy;private volatile boolean closing;private BukkitTask timer;
    private boolean activeExternal;private CompletableFuture<Void> externalDone=CompletableFuture.completedFuture(null);private CompletionStage<Void> closeReceipt;
    private final Map<UUID,Offer> offers=new HashMap<>();private final Set<UUID> liveReceipts=new HashSet<>();
    private static final class View implements InventoryHolder{Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();public Inventory getInventory(){return inventory;}}
    public LimitService(JavaPlugin plugin){this(plugin,new LimitBank());}public LimitService(JavaPlugin plugin,LimitBank bank){this.plugin=plugin;this.bank=bank;inventoryEvidence=new PlayerSaveEvidence(plugin);auditQueue=new LimitAudit(plugin);repository=new LimitRepository(plugin.getDataFolder().toPath().resolve("personal-orders.yml"));}
    public LimitRepository repository(){return repository;}
    public void start(){reloadConfig();repository.loadAsync().thenCompose(ignored->repository.compactHistory()).whenComplete((saved,error)->{if(error!=null&&!closing)plugin.getLogger().log(java.util.logging.Level.WARNING,"Личные заявки недоступны; городской рынок продолжает работать",error);});plugin.getServer().getPluginManager().registerEvents(this,plugin);timer=SuiteScheduler.get().runTaskTimer(plugin,this::pulse,20,20);}
    public void reloadConfig(){offers.clear();try{Object flag=plugin.getConfig().get("personal-orders.enabled",true);if(!(flag instanceof Boolean b))throw new IllegalArgumentException("personal-orders.enabled: требуется true/false");var names=plugin.getConfig().getStringList("personal-orders.materials");if(names.isEmpty())names=List.of("STONE","COBBLESTONE","OAK_LOG","SPRUCE_LOG","BIRCH_LOG","SAND","GLASS","IRON_INGOT","COPPER_INGOT","GOLD_INGOT","COAL","WHEAT");var next=new TreeSet<String>();for(String name:names){var material=Material.matchMaterial(name);if(material==null||!material.isItem()||material.isAir())throw new IllegalArgumentException("Неверный материал личного рынка: "+name);next.add(material.name());}if(next.size()>256)throw new IllegalArgumentException("Слишком большой список материалов");products=Set.copyOf(next);enabled=b;configIssue="";}catch(RuntimeException error){enabled=false;configIssue=error.getMessage();plugin.getLogger().warning("Личные заявки приостановлены: "+configIssue);}}
    public Set<String> products(){return products;}
    private void usable(Player player,boolean creation){if(closing||SuiteState.frozen(plugin.getName())||!plugin.isEnabled())throw new IllegalStateException("Рынок на паузе; резерв сохранён");if(!player.hasPermission("neverlandtownymarket.use")||!player.hasPermission("neverlandtownymarket.personal"))throw new IllegalArgumentException("Нет доступа к личным заявкам");if(player.getGameMode()!=GameMode.SURVIVAL&&player.getGameMode()!=GameMode.ADVENTURE)throw new IllegalArgumentException("Личные сделки доступны в выживании и приключении");if(!repository.writable())throw new IllegalStateException("Журнал личных заявок недоступен; резерв сохранён");if(busy||repository.busy())throw new IllegalStateException("Предыдущее действие сохраняется. Попробуйте через секунду");if(repository.state().receipts().values().stream().anyMatch(r->r.owner().equals(player.getUniqueId())&&r.status()==ReceiptStatus.PENDING))throw new IllegalStateException("Прошлое действие ожидает сверки; сообщите администрации");if(creation&&!creationIssue().isEmpty())throw new IllegalStateException(creationIssue());if(creation&&(!enabled||!plugin.getConfig().getBoolean("enabled",true)))throw new IllegalStateException(configIssue.isBlank()?"Новые личные заявки отключены; свои остатки можно забрать":configIssue);}
    private String creationIssue(){var state=repository.state();return state.fills().size()>=MAX_FILLS?"Журнал сделок заполнен: новые заявки и сделки приостановлены. Остатки можно вернуть и забрать; сообщите администрации":state.orders().size()>=MAX_ORDERS||state.receipts().size()>=MAX_RECEIPTS?"Журнал заявок заполнен: новые заявки приостановлены. Остатки можно вернуть и забрать; сообщите администрации":"";}
    private void pruneOffers(){long now=System.currentTimeMillis();offers.values().removeIf(o->o.expires()<=now);}
    private String product(String raw,boolean creating){var material=Material.matchMaterial(raw);if(material==null||material.isAir()||!material.isItem()||creating&&!products.contains(material.name()))throw new IllegalArgumentException("Этот товар недоступен. Список: /townymarket personal");return material.name();}
    public Offer offer(Player p,Side side,String raw,int quantity,long cents){try(var guard=SuiteState.guard()){usable(p,true);pruneOffers();if(offers.size()>=1024&&!offers.containsKey(p.getUniqueId()))throw new IllegalStateException("Слишком много незавершённых подтверждений; попробуйте через минуту");String product=product(raw,true);if(quantity<1||quantity>3456||cents<1||cents>100_000_000_000L/quantity)throw new IllegalArgumentException("Партия: 1–3456; итог не больше 1 000 000 000 монет");if(side==Side.BUY&&!bank.ready(p.getUniqueId()))throw new IllegalStateException("Дождитесь подключения экономики Towny");if(side==Side.SELL&&LimitInventory.take(p.getInventory().getStorageContents(),Material.valueOf(product),quantity)==null)throw new IllegalArgumentException("Не хватает обычных предметов без имени, чар и других изменений");var offer=new Offer(UUID.randomUUID(),p.getUniqueId(),side,product,quantity,cents,System.currentTimeMillis()+60_000);offers.put(p.getUniqueId(),offer);return offer;}}
    public void confirm(Player p,UUID token){try(var guard=SuiteState.guard()){usable(p,true);var offer=offers.get(p.getUniqueId());if(offer==null||!offer.token().equals(token)||offer.expires()<=System.currentTimeMillis())throw new IllegalArgumentException("Подтверждение устарело. Создайте заявку заново");product(offer.product(),true);offers.remove(p.getUniqueId());var before=repository.state();UUID receipt=UUID.randomUUID();var next=LimitBook.prepareOrder(before,offer.token(),receipt,p.getUniqueId(),offer.side(),offer.product(),offer.quantity(),offer.cents(),System.currentTimeMillis());external(p,before,next,receipt);}}
    public void cancel(Player p,UUID id){try(var guard=SuiteState.guard()){usable(p,false);var before=repository.state();save(p,before,LimitBook.cancel(before,p.getUniqueId(),id,System.currentTimeMillis()),"Остаток заявки возвращён в раздел получения");}}
    public void claimCash(Player p){try(var guard=SuiteState.guard()){usable(p,false);if(!bank.ready(p.getUniqueId()))throw new IllegalStateException("Дождитесь подключения экономики Towny");var before=repository.state();long amount=Math.min(100_000_000_000L,before.cash(p.getUniqueId()));if(amount<1)throw new IllegalArgumentException("Нет средств для получения");UUID receipt=UUID.randomUUID();external(p,before,LimitBook.claimCash(before,receipt,p.getUniqueId(),amount,System.currentTimeMillis()),receipt);}}
    public void claimItems(Player p,String raw,int quantity){try(var guard=SuiteState.guard()){usable(p,false);String product=product(raw,false);var before=repository.state();if(quantity<1||quantity>3456)throw new IllegalArgumentException("Получение: 1–3456 предметов за раз");if(LimitInventory.give(p.getInventory().getStorageContents(),Material.valueOf(product),quantity)==null)throw new IllegalArgumentException("Освободите место в инвентаре");UUID receipt=UUID.randomUUID();external(p,before,LimitBook.claimItems(before,receipt,p.getUniqueId(),product,quantity,System.currentTimeMillis()),receipt);}}
    private void save(Player player,State before,State next,String message){busy=true;repository.commit(before,next).whenComplete((saved,error)->{try(var guard=SuiteState.guard()){busy=false;}if(error!=null){warn(error);reply(player,"Изменение не подтверждено; резерв сохранён. Сообщите администрации");}else reply(player,message);});}
    private void external(Player player,State before,State next,UUID receipt){busy=true;externalDone=new CompletableFuture<>();liveReceipts.add(receipt);reply(player,"Сохраняем резерв. Дождитесь результата…");repository.commit(before,next).whenComplete((saved,error)->{
        if(error!=null){warn(error);reply(player,"Резерв не подтверждён; внешнее списание не выполнялось");finish(receipt);return;}
        if(closing||!plugin.isEnabled()||SuiteState.frozen(plugin.getName())){finish(receipt);return;}
        try{var scheduled=player.getScheduler().runDelayed(plugin,task->perform(player,receipt),()->notPerformed(receipt),1);if(scheduled==null)notPerformed(receipt);}catch(RuntimeException rejected){warn(rejected);finish(receipt);}
    });}
    private void notPerformed(UUID id){try(var guard=SuiteState.guard()){if(closing||!repository.writable()){finish(id);return;}settle(null,id,false);}}
    private void perform(Player p,UUID id){
        final Receipt receipt;try(var guard=SuiteState.guard()){
        receipt=repository.state().receipts().get(id);if(receipt==null||receipt.status()!=ReceiptStatus.PENDING||!liveReceipts.contains(id))return;
        if(closing||SuiteState.frozen(plugin.getName())){finish(id);return;}activeExternal=true;}
        try{
        if(!p.isOnline()||!p.getUniqueId().equals(receipt.owner())||!p.hasPermission("neverlandtownymarket.personal")||!p.hasPermission("neverlandtownymarket.use")||(p.getGameMode()!=GameMode.SURVIVAL&&p.getGameMode()!=GameMode.ADVENTURE)){settle(p,id,false);return;}
            boolean applied;
            if(receipt.kind()==Kind.BUY_FUND||receipt.kind()==Kind.CASH_CLAIM){if(!bank.ready(receipt.owner())){settle(p,id,false);return;}applied=bank.move(receipt.owner(),id,receipt.cents(),receipt.kind()==Kind.CASH_CLAIM);}
            else{
                var material=Material.valueOf(receipt.product());var plan=receipt.kind()==Kind.SELL_STOCK?LimitInventory.take(p.getInventory().getStorageContents(),material,receipt.quantity()):LimitInventory.give(p.getInventory().getStorageContents(),material,receipt.quantity());if(plan==null){settle(p,id,false);return;}
                final PlayerSaveEvidence.Prepared proof;try{proof=inventoryEvidence.prepare(p,id);}catch(java.io.IOException unsupported){warn(unsupported);settle(p,id,false);return;}
                p.getInventory().setStorageContents(plan);
                inventoryEvidence.saveAndVerify(p,proof).whenComplete((verified,error)->{if(error!=null||!Boolean.TRUE.equals(verified)){review(p,receipt,error==null?new java.io.IOException("В файле игрока нет подтверждённой квитанции перемещения предметов"):error);return;}settle(p,id,true);});return;
            }
            settle(p,id,applied);
        }catch(Exception|LinkageError error){review(p,receipt,error);}
    }
    private void review(Player player,Receipt receipt,Throwable error){try{warn(error);audit(receipt,"REVIEW","Внешняя операция требует сверки; token=[personal-market:"+receipt.id()+"]");reply(player,"Операция ожидает сверки администратора. Повторного списания не будет. ID: "+receipt.id());}finally{finish(receipt.id());}}
    private void settle(Player player,UUID id,boolean applied){try(var guard=SuiteState.guard()){var before=repository.state();var receipt=before.receipts().get(id);if(receipt==null||receipt.status()!=ReceiptStatus.PENDING){finish(id);return;}final State next;try{next=LimitBook.resolve(before,id,applied,System.currentTimeMillis());}catch(RuntimeException error){warn(error);finish(id);return;}repository.commit(before,next).whenComplete((saved,error)->{try{if(error!=null){warn(error);reply(player,"Результат требует сверки администратора. ID: "+id);return;}audit(receipt,applied?"CONFIRMED":"NOT_APPLIED","Подтверждение внешнего результата");reply(player,applied?"Операция сохранена. Заявки и получение: /townymarket personal":"Операция не выполнена. Деньги и предметы остаются у владельца или в разделе получения");}finally{finish(id);}});}}
    private void finish(UUID id){try(var guard=SuiteState.guard()){if(!liveReceipts.remove(id))return;busy=false;activeExternal=false;externalDone.complete(null);}}
    private void pulse(){pruneOffers();if(closing||busy||!repository.writable()||repository.busy()||!enabled||!plugin.getConfig().getBoolean("enabled",true))return;try{var before=repository.state();var next=LimitBook.match(before,System.currentTimeMillis(),20);if(next.equals(before))return;busy=true;repository.commit(before,next).whenComplete((saved,error)->{try(var guard=SuiteState.guard()){busy=false;}if(error!=null){warn(error);return;}for(int i=before.fills().size();i<saved.fills().size();i++){var f=saved.fills().get(i);auditQueue.fill(f);}});}catch(RuntimeException error){warn(error);}}
    public void resolve(CommandSender sender,UUID id,boolean applied){try(var guard=SuiteState.guard()){if(!sender.hasPermission("neverlandtownymarket.admin"))throw new IllegalArgumentException("Нужно право администратора рынка");if(closing||busy||repository.busy()||!repository.writable())throw new IllegalStateException("Дождитесь сохранения или восстановите журнал");var before=repository.state();var r=before.receipts().get(id);if(r==null||r.status()!=ReceiptStatus.PENDING||liveReceipts.contains(id))throw new IllegalArgumentException("Нет остановленной операции для сверки");String administrator=sender.getName();busy=true;repository.commit(before,LimitBook.resolve(before,id,applied,System.currentTimeMillis())).whenComplete((saved,error)->{try(var guard2=SuiteState.guard()){busy=false;}if(error!=null){warn(error);return;}audit(r,"RECONCILED",administrator+": "+(applied?"applied":"not-applied"));SuiteScheduler.reply(plugin,sender,()->MarketService.tell(sender,"Результат сверки сохранён: "+id));});}}
    public Map<String,Object> snapshot(UUID owner){var state=repository.state();var orders=new ArrayList<Map<String,Object>>();for(var o:state.orders().values())if(o.status()==Status.OPEN||owner!=null&&o.owner().equals(owner))orders.add(Map.of("id",o.id().toString(),"owner",o.owner().toString(),"side",o.side().name(),"product",o.product(),"quantity",o.quantity(),"remaining",o.remaining(),"unitCents",o.unitCents(),"status",o.status().name(),"created",o.created()));return Map.of("ready",repository.readable(),"enabled",enabled,"orders",List.copyOf(orders),"cashCents",owner==null?0L:state.cash(owner),"items",owner==null?Map.of():state.items().getOrDefault(owner,Map.of()),"pending",owner==null?0L:state.receipts().values().stream().filter(r->r.owner().equals(owner)&&r.status()==ReceiptStatus.PENDING).count());}
    private void audit(Receipt r,String status,String note){auditQueue.receipt(r,status,note);}
    private void warn(Throwable error){plugin.getLogger().log(java.util.logging.Level.WARNING,"Личный рынок: резерв сохранён; проверьте операции PENDING",error);}
    private void reply(Player player,String text){if(player!=null&&!closing&&plugin.isEnabled()&&!SuiteState.frozen(plugin.getName()))try{SuiteScheduler.reply(plugin,player,()->{if(player.isOnline())MarketService.tell(player,text);});}catch(RuntimeException ignored){}}
    public CompletionStage<Void> prepareClose(){try(var guard=SuiteState.guard()){if(closeReceipt!=null)return closeReceipt;closing=true;offers.clear();if(timer!=null)timer.cancel();if(!activeExternal)externalDone.complete(null);closeReceipt=externalDone.thenCompose(ignored->repository.prepareClose()).handle((ignored,error)->{inventoryEvidence.close();return error;}).thenCompose(error->auditQueue.closeAsync().thenCompose(ignored->error==null?CompletableFuture.completedFuture(null):CompletableFuture.failedFuture(error)));return closeReceipt;}}public void awaitClosed(){var done=prepareClose().toCompletableFuture();if(SuiteState.held()&&!done.isDone())throw new IllegalStateException("Дождитесь личных операций вне общей блокировки");try{done.get(10,TimeUnit.SECONDS);}catch(Exception error){throw new IllegalStateException("Личная операция ещё завершается",error);}}
    public boolean command(CommandSender sender,String[] args){if(args.length==0||!Set.of("personal","limit-buy","limit-sell","limit-confirm","limit-cancel","limit-cash","limit-items","limit-inspect","limit-resolve").contains(args[0].toLowerCase(Locale.ROOT)))return false;
        try(var guard=SuiteState.guard()){String action=args[0].toLowerCase(Locale.ROOT);if(action.equals("limit-inspect")||action.equals("limit-resolve")){if(!sender.hasPermission("neverlandtownymarket.admin"))throw new IllegalArgumentException("Нужно право администратора рынка");
            if(action.equals("limit-inspect")){if(args.length==1){repository.state().receipts().values().stream().filter(r->r.status()==ReceiptStatus.PENDING).limit(50).forEach(r->MarketService.tell(sender,r.id()+" "+r.kind()+" "+r.owner()+" "+r.product()+" x"+r.quantity()+"; "+MarketData.money(r.cents())));MarketService.tell(sender,"Сверяйте логи банка по [personal-market:UUID] и сохранённую квитанцию neverlandtownymarket:personal_market_receipt вместе с инвентарём. /townymarket limit-inspect <UUID>");}
                else if(args.length==2){inspectReceipt(sender,UUID.fromString(args[1]));}else throw new IllegalArgumentException("/townymarket limit-inspect [UUID]");return true;}
            if(args.length!=4||!args[3].equalsIgnoreCase("confirm")||!Set.of("applied","not-applied").contains(args[2]))throw new IllegalArgumentException("/townymarket limit-resolve <UUID> <applied|not-applied> confirm");resolve(sender,UUID.fromString(args[1]),args[2].equals("applied"));return true;}
            if(!(sender instanceof Player player))throw new IllegalArgumentException("Личные заявки открываются в игре");switch(action){
                case "personal"->open(player,args.length>1?args[1]:"mine",args.length>2?Integer.parseInt(args[2])-1:0);
                case "limit-buy","limit-sell"->{if(args.length!=4)throw new IllegalArgumentException("/townymarket "+action+" <материал> <количество> <цена за штуку>");confirmMenu(player,offer(player,action.equals("limit-buy")?Side.BUY:Side.SELL,args[1],Integer.parseInt(args[2]),MarketData.cents(args[3])));}
                case "limit-confirm"->{if(args.length!=2)throw new IllegalArgumentException("Укажите UUID подтверждения");confirm(player,UUID.fromString(args[1]));}
                case "limit-cancel"->{if(args.length!=2)throw new IllegalArgumentException("/townymarket limit-cancel <UUID заявки>");cancel(player,UUID.fromString(args[1]));}
                case "limit-cash"->claimCash(player);
                case "limit-items"->{if(args.length!=3)throw new IllegalArgumentException("/townymarket limit-items <материал> <количество>");claimItems(player,args[1],Integer.parseInt(args[2]));}
                default->throw new IllegalArgumentException("Неизвестное действие");
            }
        }catch(Exception error){MarketService.tell(sender,error.getMessage()==null?"Личная операция не выполнена":error.getMessage());}return true;
    }
    private void inspectReceipt(CommandSender sender,UUID id){repository.lookupReceipt(id).whenComplete((receipt,error)->{if(error!=null)warn(error);if(closing||!plugin.isEnabled())return;try{SuiteScheduler.reply(plugin,sender,()->{if(!sender.hasPermission("neverlandtownymarket.admin"))return;if(error!=null){MarketService.tell(sender,"Архив не удалось проверить; результат операции не изменён");return;}if(receipt==null){MarketService.tell(sender,"Квитанция не найдена");return;}MarketService.tell(sender,receipt.toString());MarketService.tell(sender,receipt.status()==ReceiptStatus.PENDING?"/townymarket limit-resolve "+receipt.id()+" <applied|not-applied> confirm — только после проверки факта операции":"Результат завершён и хранится в журнале или архиве; повторная выплата недоступна");});}catch(RuntimeException ignored){}});}
    private View view(Player player,String title){if(!player.hasPermission("neverlandtownymarket.use")||!player.hasPermission("neverlandtownymarket.personal"))throw new IllegalArgumentException("Нет доступа к личному рынку");var view=new View();view.inventory=MenuStyle.inventory(plugin,view,54,title);return view;}
    public void open(Player player,String requested,int requestedPage){try(var guard=SuiteState.guard()){
        String mode=Set.of("book","mine","pickup").contains(requested)?requested:"mine";var v=view(player,"Личные заявки рынка");var state=repository.state();int page=Math.max(0,requestedPage);int pages;
        if(mode.equals("pickup")){var items=new ArrayList<>(state.items().getOrDefault(player.getUniqueId(),Map.of()).entrySet());items.sort(Map.Entry.comparingByKey());pages=Math.max(1,(items.size()+35)/36);page=Math.min(page,pages-1);for(int i=page*36;i<Math.min(items.size(),page*36+36);i++){var e=items.get(i);int amount=(int)Math.min(64,e.getValue());button(v,i%36,Material.valueOf(e.getKey()),label(e.getKey()),List.of("Ожидает получения: "+e.getValue(),"Нажмите: забрать до "+amount+" шт.","Предметы сохраняются при выходе и рестарте."),()->claimItems(player,e.getKey(),amount));}}
        else{var list=state.orders().values().stream().filter(o->mode.equals("book")?o.status()==Status.OPEN:o.owner().equals(player.getUniqueId())).sorted(Comparator.comparingLong(Order::created).reversed().thenComparing(Order::id)).toList();pages=Math.max(1,(list.size()+35)/36);page=Math.min(page,pages-1);for(int i=page*36;i<Math.min(list.size(),page*36+36);i++){var o=list.get(i);var lines=new ArrayList<String>(List.of(o.side()==Side.BUY?"Покупка: не дороже указанной цены":"Продажа: не дешевле указанной цены","За штуку: "+MarketData.money(o.unitCents()),"Осталось: "+o.remaining()+" / "+o.quantity(),"Состояние: "+status(o.status()),"ID: "+o.id()));if(o.owner().equals(player.getUniqueId())&&o.status()==Status.OPEN)lines.add("Нажмите: подтвердить возврат остатка");button(v,i%36,Material.valueOf(o.product()),(o.side()==Side.BUY?"Купить ":"Продать ")+label(o.product()),lines,()->{if(o.owner().equals(player.getUniqueId())&&o.status()==Status.OPEN)cancelMenu(player,o);});}}
        final int selectedPage=page;button(v,39,Material.PAPER,"Как создать заявку",List.of("/townymarket limit-buy <товар> <кол-во> <цена>","/townymarket limit-sell <товар> <кол-во> <цена>","Цена задаётся за один предмет.","Резервируется вся сумма или весь товар.","Только обычные предметы без изменений.","Товары: "+String.join(", ",new TreeSet<>(products))),()->{});
        button(v,41,Material.EMERALD,"Забрать деньги: "+MarketData.money(state.cash(player.getUniqueId())),List.of("Выручка, разница цены и возвращённый резерв.","Нажмите: перечислить на личный счёт.","Никакой новой валюты не создаётся."),()->claimCash(player));
        long pending=state.receipts().values().stream().filter(r->r.owner().equals(player.getUniqueId())&&r.status()==ReceiptStatus.PENDING).count();button(v,43,pending>0?Material.CLOCK:Material.BOOK,"Состояние операций",List.of(repository.readable()?"Журнал загружен":"Журнал недоступен; резерв сохранён",!creationIssue().isEmpty()?creationIssue():enabled?"Новые заявки разрешены":"Новые заявки отключены","Требуют завершения или сверки: "+pending,"Условия сделки — цена более ранней заявки.","Сделки с собой исключены."),()->{});
        if(page>0)button(v,45,Material.ARROW,"Предыдущая",List.of(),()->open(player,mode,selectedPage-1));button(v,46,Material.COMPASS,"Все заявки",List.of(),()->open(player,"book",0));button(v,47,Material.WRITABLE_BOOK,"Мои заявки",List.of(),()->open(player,"mine",0));button(v,48,Material.BARREL,"Получить товары",List.of(),()->open(player,"pickup",0));button(v,49,Material.SUNFLOWER,"Обновить",List.of("Страница "+(page+1)+" / "+pages),()->open(player,mode,selectedPage));button(v,51,Material.CHEST,"Городской рынок",List.of(),()->{player.closeInventory();player.performCommand("townymarket local");});if(page+1<pages)button(v,53,Material.ARROW,"Следующая",List.of(),()->open(player,mode,selectedPage+1));player.openInventory(v.inventory);
    }}
    private void confirmMenu(Player player,Offer offer){var v=view(player,"Подтверждение личной заявки");button(v,13,Material.valueOf(offer.product()),label(offer.product()),List.of("Количество: "+offer.quantity(),"Цена за штуку: "+MarketData.money(offer.cents()),offer.side()==Side.BUY?"Резерв с личного счёта: "+MarketData.money(offer.cents()*offer.quantity()):"Весь товар будет забран из инвентаря в резерв.",offer.side()==Side.BUY?"Исполнение только по этой цене или дешевле.":"Исполнение только по этой цене или дороже.","Невыполненный остаток можно вернуть.","Подтверждение действует 60 секунд."),()->{});button(v,29,Material.LIME_CONCRETE,"Подтвердить резерв",List.of(),()->{confirm(player,offer.token());player.closeInventory();});button(v,33,Material.ARROW,"Назад",List.of(),()->open(player,"mine",0));player.openInventory(v.inventory);}
    private void cancelMenu(Player player,Order order){var v=view(player,"Вернуть остаток заявки?");button(v,13,Material.valueOf(order.product()),label(order.product()),List.of("Остаток: "+order.remaining(),"Вернутся только ещё не проданные товары", "или деньги за ещё не купленные товары.","Получение — в личном меню рынка."),()->{});button(v,29,Material.LIME_CONCRETE,"Вернуть остаток",List.of(),()->{cancel(player,order.id());player.closeInventory();});button(v,33,Material.ARROW,"Назад",List.of(),()->open(player,"mine",0));player.openInventory(v.inventory);}
    private static final ru.neverland.localization.MaterialLabels NAMES=new ru.neverland.localization.MaterialLabels();
    private static String label(String product){return NAMES.name(product);}
    private static String status(Status status){return switch(status){case FUNDING->"Ожидает подтверждения резерва";case OPEN->"Исполняется";case CANCELLED->"Остаток возвращён";case FILLED->"Исполнена";};}
    private static void button(View v,int slot,Material material,String title,List<String> lore,Runnable action){var item=new ItemStack(material);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("§f"+title));meta.setLore(MenuStyle.loreStrings(lore.stream().map(s->"§7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot,item);v.actions.put(slot,action);}
    @EventHandler public void click(InventoryClickEvent event){try(var guard=SuiteState.guard()){if(!(event.getView().getTopInventory().getHolder()instanceof View v))return;event.setCancelled(true);if(!(event.getWhoClicked()instanceof Player player))return;if(closing||SuiteState.frozen(plugin.getName()))return;Runnable action=v.actions.get(event.getRawSlot());if(action==null)return;SuiteScheduler.entity(plugin,player,()->{if(player.isOnline()&&player.getOpenInventory().getTopInventory()==v.inventory){try{if(!player.hasPermission("neverlandtownymarket.personal")||!player.hasPermission("neverlandtownymarket.use"))throw new IllegalArgumentException("Доступ изменён");action.run();}catch(Exception error){MarketService.tell(player,error.getMessage());}}});}}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder()instanceof View)event.setCancelled(true);}
}
